<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageUrgentVO;

trait MessageUrgentAttributeHolder
{
    protected MessageUrgentVO|bool|null $urgent = null;
    protected bool $urgentAssigned = false;

    public function getUrgentOrCurrent(MessageUrgentVO $urgent): MessageUrgentVO
    {
        if ($this->urgentAssigned) {
            \assert(null !== $this->urgent);
            return MessageUrgentVO::from($this->urgent);
        } else {
            return $urgent;
        }
    }
    public function urgentTryBuildInitial(ConstraintFailList $error): ?MessageUrgentVO
    {
        return  MessageUrgentVO::tryFrom($this->urgentAssigned ? $this->urgent : false, $error);
    }
    public function urgent(MessageUrgentVO|bool $urgent): static
    {
        $this->urgent = $urgent;
        $this->urgentAssigned = true;
        return $this;
    }
    public function isUrgent(): ?bool
    {
        return $this->urgent instanceof MessageUrgentVO ? $this->urgent->value() : $this->urgent;
    }
    public function isUrgentAssigned(): bool
    {
        return $this->urgentAssigned;
    }
    public function writeUrgentTo(mixed $att): void
    {
        if ($this->urgentAssigned) {
            \assert(null !== $this->urgent);
            $att->urgent($this->urgent);
        }
    }
    public function readUrgentFrom(mixed $att): void
    {
        if ($att->isUrgentAssigned()) {
            $urgent = $att->isUrgent();
            \assert(null !== $urgent);
            $this->urgent($urgent);
        }
    }
    public function unsetUrgent(): static
    {
        $this->urgentAssigned = false;
        return $this;
    }
    protected function withDefaultUrgent(): void
    {
        if ($this->urgent === null) {
            $this->urgent = false;
        }
    }
    protected function withAssertedUrgentRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->urgentAssigned = $this->urgentAssigned) {
            $value->urgent = MessageUrgentVO::tryFrom($this->urgent, $errorsList);
        }
    }
}
